def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n <= 14:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = 0
    for a in op:
        if a == 'C':
            opp_c += 1
    opp_c_rate = opp_c / n

    k = 10 if n > 10 else n
    recent_c = 0
    for a in op[-k:]:
        if a == 'C':
            recent_c += 1
    recent_c_rate = recent_c / k

    opp_d_streak = 0
    for a in reversed(op):
        if a == 'D':
            opp_d_streak += 1
        else:
            break

    mutual_c_streak = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 'C' and op[i] == 'C':
            mutual_c_streak += 1
        else:
            break

    forgive = 0
    punish = 0
    recent_for = 0
    recent_pun = 0
    for i in range(1, n):
        if my[i - 1] == 'D':
            if op[i] == 'C':
                forgive += 1
                if i > n - 8:
                    recent_for += 1
            else:
                punish += 1
                if i > n - 8:
                    recent_pun += 1

    total_my_D = 0
    for a in my:
        if a == 'D':
            total_my_D += 1

    my_last = my[-1]
    op_last = op[-1]

    if total_my_D == 0 and op_last == 'C' and n < 25 and recent_c_rate > 0.25 and opp_c_rate < 0.45:
        return 'C'

    exploit = False
    if total_my_D > 0:
        if punish == 0 and forgive >= 1:
            exploit = True
        elif recent_for >= 3 and recent_for > 2 * recent_pun and recent_c_rate > 0.60:
            exploit = True
        elif forgive >= 5 and forgive > 2 * punish + 2 and recent_c_rate > 0.60:
            exploit = True

    hostile = False
    if n >= 8:
        if recent_c_rate < 0.20 or opp_c_rate < 0.30 or opp_d_streak >= 5:
            hostile = True
    if hostile:
        return 'D'

    if n == 98:
        if exploit:
            if op_last == 'C':
                return 'D'
            if opp_c_rate > 0.55 and recent_c_rate > 0.50 and opp_d_streak <= 2:
                return 'C'
            return 'D'
        if recent_c_rate < 0.45:
            return 'D'
        return 'C'

    if exploit:
        if op_last == 'D':
            if recent_c_rate > 0.60 and opp_d_streak <= 2:
                return 'C'
            if opp_c_rate > 0.55 and recent_c_rate > 0.50 and opp_d_streak <= 2:
                return 'C'
            return 'D'
        return 'D'

    if my_last == 'D' and op_last == 'C':
        if recent_c_rate > 0.50 or opp_c_rate > 0.55:
            return 'C'
        return 'D'

    if op_last == 'D':
        if recent_c_rate > 0.60 and opp_d_streak <= 2:
            if opp_d_streak == 1 or my_last == 'D':
                return 'C'
            return 'D'
        if opp_c_rate > 0.55 and recent_c_rate > 0.50 and opp_d_streak <= 2:
            if opp_d_streak == 1 or my_last == 'D':
                return 'C'
            return 'D'
        return 'D'

    if recent_c_rate < 0.30 or opp_c_rate < 0.30:
        return 'D'

    if total_my_D == 0 and n >= 15 and mutual_c_streak >= 8 and recent_c_rate > 0.85 and opp_c_rate > 0.60:
        return 'D'

    return 'C'
